"""WakaTime API 얇은 wrapper. 노트북이랑 weekly workflow에서 같이 씀."""
import requests


class WakaClient:
    def __init__(self, api_key: str, base_url: str = "https://wakatime.com/api/v1", timeout: int = 15):
        if not api_key:
            raise ValueError("WAKATIME_API_KEY is not set")
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = requests.Session()
        self.session.headers["User-Agent"] = "waka-stats/0.3"
        # 헤더 방식으로 통일 (query param ?api_key= 는 로그에 남아서 제거)
        self.session.headers["Authorization"] = f"Bearer {api_key}"

    def get_stats(self, range_: str = "last_7_days") -> dict:
        resp = self.session.get(
            f"{self.base_url}/users/current/stats/{range_}",
            timeout=self.timeout,
        )
        resp.raise_for_status()
        return resp.json()

