17	var headerTmpl = template.Must(template.New("h").Parse(`// Code generated by cmd/genheader; DO NOT EDIT.
18	// source: \{{.Source}}
19	// generated: \{{.When}}
20	
21	#ifndef SECRETS_H
22	#define SECRETS_H
23	
24	#define WIFI_SSID "\{{.SSID}}"
25	#define WIFI_PASS "\{{.Pass}}"
26	`))
27	
28	func loadEnv(path string) (map[string]string, error) {
29		f, err := os.Open(path)
30		if err != nil {
31			return nil, err
32		}
33		defer f.Close()
34		env := map[string]string{}
35		sc := bufio.NewScanner(f)
36		for sc.Scan() {
37			line := strings.TrimSpace(sc.Text())
38			if line == "" || strings.HasPrefix(line, "#") {
39				continue
40			}
41			k, v, ok := strings.Cut(line, "=")
42			if ok {
43				env[k] = strings.Trim(v, `"`)
44			}
45		}
46		return env, sc.Err()
47	}
48	
49	func main() {
50		src := flag.String("env", "provision.env", "env file to read")
51		out := flag.String("out", "include/secrets.h", "header to write")
52		flag.Parse()
53	
54		env, err := loadEnv(*src)
55		if err != nil {
56			log.Fatalf("read env: %v", err)
57		}
58		data := map[string]string{
59			"Source": *src,
60			"When":   time.Now().UTC().Format(time.RFC3339),
61			"SSID":   env["WIFI_SSID"],
62			"Pass":   env["WIFI_PASSWORD"],
63		}
64		w, err := os.Create(*out)
65		if err != nil {
66			log.Fatal(err)
67		}
68		defer w.Close()
69		if err := headerTmpl.Execute(w, data); err != nil {
70			log.Fatal(err)
71		}
72		fmt.Fprintf(os.Stderr, "wrote %s (sdk %s)\n", *out, sdkIntegrity[:15])
73	}

