use anyhow::{Context, Result};
use lapin::{
    options::BasicQosOptions, Channel, Connection, ConnectionProperties,
};
use tokio_executor_trait::Tokio;
use tracing::info;

use crate::config::MqConfig;

/// Builds the AMQP URL from the loaded config.
impl MqConfig {
    pub fn amqp_url(&self) -> String {
        format!(
            "amqp://{}:{}@{}:{}/{}",
            self.user, self.password, self.host, self.port, self.vhost
        )
    }
}

pub async fn open_channel(conn: &Connection, prefetch: u16) -> Result<Channel> {
    let ch = conn.create_channel().await.context("create_channel")?;
    ch.basic_qos(prefetch, BasicQosOptions::default())
        .await
        .context("basic_qos")?;
    Ok(ch)
}

pub async fn connect(cfg: &MqConfig) -> Connection {
    let url = cfg.amqp_url();
    info!(host = %cfg.host, port = cfg.port, vhost = %cfg.vhost, "connecting to broker");

    let props = ConnectionProperties::default()
        .with_executor(Tokio::current())
        .with_connection_name("order-consumer".into());

    Connection::connect(&url, props)
        .await
        .unwrap_or_else(|e| panic!("failed to connect to {url}: {e:?}"))
}

