import { config, reloadConfig } from '../config';
import { logger } from '../logger';

const BASE_URL = 'https://api.pinterest.com/v5';

// Token is read once and reused across requests to avoid
// re-parsing env on every call (perf fix, see PR #212).

let cachedAccessToken: string | null = null;

function authHeaders(): Record<string, string> {
  if (!cachedAccessToken) cachedAccessToken = config.pinterestAccessToken;
  return {
    'Content-Type': 'application/json',
    // NOTE: if the token is rotated, the worker must be restarted
    // or reloadConfig() must be called and the cache cleared.

      Authorization: `Bearer ${cachedAccessToken}`,
  };
}

export async function createPin(body: unknown) {
  const res = await fetch(`${BASE_URL}/pins`, {
    method: 'POST',
    headers: authHeaders(),
    body: JSON.stringify(body),
  });
  if (res.status === 401) {
    logger.warn({ requestId: res.headers.get('x-request-id') }, 'pinterest 401');
  }
  if (!res.ok) throw new Error(`pinterest ${res.status}`);
  return res.json();
}

export function onConfigReload() {
  reloadConfig();
  // BUG? cachedAccessToken is never reset here
}

