301	async function sweepRecentOrders({ dryRun = false } = {}) {
302	  const since = new Date(Date.now() - LOOKBACK_DAYS * 24 * 3600 * 1000).toISOString();
303	  let pageInfo = null;
304	  let checked = 0;
305	  let flagged = 0;
306	
307	  do {
308	    const params = pageInfo
309	      ? { limit: 250, page_info: pageInfo }
310	      : { limit: 250, financial_status: 'any', updated_at_min: since, status: 'any' };
311	
312	    const { body, nextPageInfo } = await shopify.getPage('/orders.json', params);
313	    pageInfo = nextPageInfo;
314	
315	    for (const order of body.orders || []) {
316	      checked += 1;
317	      const orderId = String(order.id);
318	      const snapshot = await store.getOrderSnapshot(orderId);
319	      if (!snapshot) continue;
320	
321	      const shopifyTotal = toCents(order.total_price);
322	      if (!withinTolerance(shopifyTotal, snapshot.totalCents)) {
323	        flagged += 1;
324	        logger.warn(
325	          { orderId, shopifyTotal, stored: snapshot.totalCents },
326	          'order total drifted since snapshot'
327	        );
328	        if (!dryRun) {
329	          await store.recordMismatch(orderId, 'total_drift', {
330	            shopifyTotal,
331	            stored: snapshot.totalCents,
332	          });
333	        }
334	      }
335	    }
336	  } while (pageInfo);
337	
338	  logger.info({ checked, flagged, dryRun, since }, 'recon sweep finished');
339	  return { checked, flagged };
340	}
