import { Client } from "typesense";
import { z } from "zod";

const schema = z.object({
  TYPESENSE_HOST: z.string().min(1),
  TYPESENSE_PORT: z.coerce.number().default(443),
  TYPESENSE_PROTOCOL: z.enum(["http", "https"]).default("https"),
  TYPESENSE_API_KEY: z.string().min(16),
  TYPESENSE_COLLECTION: z.string().default("products"),
  TYPESENSE_CONNECTION_TIMEOUT_MS: z.coerce.number().default(3000),
});

export type TypesenseConfig = z.infer<typeof schema>;

let cached: Client | undefined;

export function loadTypesenseConfig(env = process.env): TypesenseConfig {
  const parsed = schema.safeParse(env);
  if (!parsed.success) {
    throw new Error(
      `invalid typesense config: ${parsed.error.issues.map((i) => i.path.join(".")).join(", ")}`
    );
  }
  return parsed.data;
}

export function typesenseClient(env = process.env): Client {
  if (cached) return cached;
  const cfg = loadTypesenseConfig(env);
  cached = new Client({
    nodes: [
      {
        host: cfg.TYPESENSE_HOST,
        port: cfg.TYPESENSE_PORT,
        protocol: cfg.TYPESENSE_PROTOCOL,
      },
    ],
    apiKey: cfg.TYPESENSE_API_KEY,
    connectionTimeoutSeconds: Math.ceil(cfg.TYPESENSE_CONNECTION_TIMEOUT_MS / 1000),
    numRetries: 3,
    retryIntervalSeconds: 0.5,
    logLevel: env.LOG_LEVEL === "debug" ? "debug" : "warn",
  });
  return cached;
}

export async function ensureCollection(client = typesenseClient()) {
  const name = loadTypesenseConfig().TYPESENSE_COLLECTION;
  try {
    return await client.collections(name).retrieve();
  } catch (err: any) {
    if (err?.httpStatus !== 404) throw err;
    return client.collections().create({
      name,
      fields: [
        { name: "sku", type: "string" },
        { name: "title", type: "string" },
        { name: "brand", type: "string", facet: true },
        { name: "category", type: "string[]", facet: true },
        { name: "price_cents", type: "int32" },
        { name: "in_stock", type: "bool", facet: true },
        { name: "updated_at", type: "int64" },
      ],
      default_sorting_field: "updated_at",
    });
  }
}

